import argparse
import os
from PIL import Image
from string import Template

IMAGE_TEMPLATE = Template("""
-- Generated image data ImageToRBX

local image = {
$IMAGE_DATA
}

return image
""")

LUA_TEMPLATE = Template("""
-- Generated by ImageToRBX

local Players = game:GetService("Players")
local player = Players.LocalPlayer

local image = {
$IMAGE_DATA
}

local gui = Instance.new("ScreenGui")
gui.Name = "Container"
gui.Parent = player.PlayerGui

local frame = Instance.new("Frame")
frame.Name = "ImageFrame"
frame.Position = UDim2.new(0.058,0,0.047,0)
frame.Size = UDim2.new(0.408,0,0.455,0)
frame.BorderSizePixel = 0
frame.Parent = gui

local rows = #image
local cols = #image[1]

local grid = Instance.new("UIGridLayout")
grid.CellSize = UDim2.new(
    1 / cols,
    0,
    1 / rows,
    0
)
grid.CellPadding = UDim2.new(0,0,0,0)
grid.Parent = frame

local order = 0

for y = 1, rows do
    for x = 1, #image[y] do
        local pixel = Instance.new("Frame")
        local color = image[y][x]

        pixel.BackgroundColor3 = Color3.fromRGB(
            color[1],
            color[2],
            color[3]
        )

        pixel.BorderSizePixel = 0
        pixel.LayoutOrder = order
        pixel.Parent = frame

        if color[4] then
            pixel.BackgroundTransparency = 1 - color[4]/255
        end

        order = order + 1
    end
end
""")

def load_image(path, size):
    img = Image.open(path).convert('RGBA')
    return img.resize(size)

def build_image_data(image):
    pixels = image.load()
    width, height = image.size

    rows = []

    for y in range(height):
        row = []

        for x in range(width):
            r, g, b, a = pixels[x, y]
            row.append(f"{{{r},{g},{b},{a}}}")

        rows.append("{" + ",".join(row) + "}")

    return ",".join(rows)

def generate_image_module(image):
    image_data = build_image_data(image)

    return IMAGE_TEMPLATE.substitute(
        IMAGE_DATA=image_data
    )

def generate_lua(image):
    return LUA_TEMPLATE.substitute(
        IMAGE_DATA=build_image_data(image)
    )

def main():
    parser = argparse.ArgumentParser()
    
    # Args
    parser.add_argument("input")
    parser.add_argument("-o", "--output")
    parser.add_argument("-w", "--width", type=int, default=128)
    parser.add_argument("-H", "--height", type=int, default=96)
    parser.add_argument("--format", choices=["rbxmx", "lua"], default="rbxmx")

    args = parser.parse_args()
    
    print("Input:", args.input)
    print("Size:", args.width, "x", args.height)
    print("Format:", args.format)

    image = load_image(args.input, (args.width, args.height))

    if args.format == "lua":
        result = generate_lua(image)

        if args.output is None:
            args.output = "output.lua"

    else:
        base_xml = open("image_template.rbxmx", "r", encoding="utf-8").read()
        image_module = generate_image_module(image)

        result = base_xml.replace("//___//", image_module)

        if args.output is None:
            args.output = "output.rbxmx"
    # Write the result
    with open(args.output, "w", encoding="utf-8") as f:
        f.write(result)

    file_size = os.path.getsize(args.output)
    print("Done:", args.output)
    print("Size:", file_size, "bytes")

if __name__ == "__main__":
    main()